Method.Source:
    public void init()
    {
        next init();

        /// CB501_ISP_Security
        /// When the parameter is set to ‘yes’, the ‘+new’ button on the workspace ‘Purchase Order Preparation’
        /// will be enabled for any user that has the ISP XDS security role assigned. When the parameter is set to no, any users with the security role
        /// will see the button greyed out and they will not be able to create new POs.
        boolean allowISPCreatePO = METVendParameters::find().allowISPCreatePO();
        NewPurchaseOrder.enabled(allowISPCreatePO);
        CreateTile.enabled(allowISPCreatePO);
    }
